import{_ as t,o as a,c as o,a4 as n}from"./chunks/framework.Dsbb2oA0.js";const h=JSON.parse('{"title":"CAD Drawing Operations · Backend MxServiceCode Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/9.AIManual/3.BackendMxServiceCodeGuide.md","filePath":"en/docs/9.AIManual/3.BackendMxServiceCodeGuide.md"}'),s={name:"en/docs/9.AIManual/3.BackendMxServiceCodeGuide.md"};function i(d,e,r,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="cad-drawing-operations-·-backend-mxservicecode-guide" tabindex="-1">CAD Drawing Operations · Backend MxServiceCode Guide <a class="header-anchor" href="#cad-drawing-operations-·-backend-mxservicecode-guide" aria-label="Permalink to &quot;CAD Drawing Operations · Backend MxServiceCode Guide&quot;">​</a></h1><blockquote><p>Scope: server-side CAD drawing processing (Node.js command line: format conversion, data extraction, parametric drawing generation, splitting/merging, batch export). Routing rules: see <a href="./1.EntryGuide.html">Entry Guide</a>; frontend operations: see <a href="./2.FrontendMxCadGuide.html">Frontend mxcad Guide</a>.</p></blockquote><p><strong>Contents</strong></p><ul><li><a href="#i-what-mxservicecode-is">I. What MxServiceCode Is</a></li><li><a href="#ii-program-acquisition--directory-structure">II. Program Acquisition &amp; Directory Structure</a></li><li><a href="#iii-local-reference-docs-must-read">III. Local Reference Docs (must read)</a></li><li><a href="#iv-task--command-selection-quick-reference">IV. Task → Command Selection Quick Reference</a></li><li><a href="#v-task--doc-lookup-guide">V. Task → Doc Lookup Guide</a></li><li><a href="#vi-capability-boundaries">VI. Capability Boundaries</a></li></ul><hr><h2 id="i-what-mxservicecode-is" tabindex="-1">I. What MxServiceCode Is <a class="header-anchor" href="#i-what-mxservicecode-is" aria-label="Permalink to &quot;I. What MxServiceCode Is&quot;">​</a></h2><p>MxServiceCode is a <strong>standalone Node.js command-line project</strong> for processing CAD drawing files on the backend: open/save DWG, format conversion, data extraction, parametric drawing generation, batch cutting by title block frames, merge/compare, PDF export, and so on.</p><p>How it works: <strong>invoked from the command line, it runs one command and exits — no daemon, no service to start.</strong> The entry point is <code>mxapp.js</code>; each run executes one command and prints one line of JSON to stdout; the project ships a built-in Node runtime, so the system Node is not required.</p><p><strong>Contents of the backend service zip</strong> (contains BOTH the backend service and the format conversion program mxcadassembly — the complete superset; if only the conversion program is needed, download the standalone MxConvert package instead — see the &quot;Link List&quot; in the <a href="./1.EntryGuide.html">Entry Guide</a>):</p><p><strong>Windows (the backend service zip extracts to a single top-level dir <code>MxServiceCode_TryVersion\\</code>, with two subdirectories inside):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxServiceCode_TryVersion\\    ← Top-level dir after extraction (same name as the zip)</span></span>
<span class="line"><span>├── MxServiceCode\\</span></span>
<span class="line"><span>│   ├── NODE.JS后台程序开发.doc   ← Official tutorial: how to do backend development based on this project (NOT an API doc)</span></span>
<span class="line"><span>│   ├── MxServiceCode.sln        ← Solution file</span></span>
<span class="line"><span>│   └── MxServiceCode\\           ← Project directory (all commands run here)</span></span>
<span class="line"><span>│       ├── bin\\node.exe          ← Built-in Node runtime</span></span>
<span class="line"><span>│       ├── Mx2DNode.node         ← Native module (core CAD capabilities)</span></span>
<span class="line"><span>│       ├── mxapp.js              ← Entry point (command line)</span></span>
<span class="line"><span>│       ├── package.json          ← npm run build for compilation</span></span>
<span class="line"><span>│       ├── src\\                  ← TS sources (mxcad\\ = API classes, sample\\ = feature samples, MxCommand.ts = command registration)</span></span>
<span class="line"><span>│       ├── test.bat              ← Test script</span></span>
<span class="line"><span>│       ├── empty_template.dwg    ← Blank template</span></span>
<span class="line"><span>│       ├── A3.dwg / BT.DWG       ← Title block frame / title block sample blocks</span></span>
<span class="line"><span>│       └── t1.dwg / tree.dwg     ← Test drawings</span></span>
<span class="line"><span>└── MxCAD\\</span></span>
<span class="line"><span>    └── Release\\                 ← Format conversion program directory (mxcadassembly.exe + fonts\\ + runtime deps, etc.)</span></span></code></pre></div><p><strong>Linux (the backend service zip extracts to a single top-level dir <code>MxServiceCode_TryVersion\\</code>, with two subdirectories inside):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxServiceCode_TryVersion\\    ← Top-level dir after extraction (same name as the zip)</span></span>
<span class="line"><span>├── MxServiceCode\\</span></span>
<span class="line"><span>│   ├── NODE.JS后台程序开发.doc   ← Official tutorial</span></span>
<span class="line"><span>│   └── MxServiceCode\\           ← Project directory (no .sln; the built-in runtime is \`node\`, not bin\\node.exe;</span></span>
<span class="line"><span>│                                 also contains start_demo_MxServiceCode.sh, start_demo_systemlib_MxServiceCode.sh, Linux启动说明.txt)</span></span>
<span class="line"><span>└── Linux\\</span></span>
<span class="line"><span>    └── MxCAD\\                   ← Format conversion program directory (mxcadassembly + fonts\\ + runtime deps, etc.)</span></span></code></pre></div><h2 id="ii-program-acquisition-directory-structure" tabindex="-1">II. Program Acquisition &amp; Directory Structure <a class="header-anchor" href="#ii-program-acquisition-directory-structure" aria-label="Permalink to &quot;II. Program Acquisition &amp; Directory Structure&quot;">​</a></h2><h3 id="_2-1-download-placement-fixed-temp-path-download-once-reuse-across-sessions" tabindex="-1">2.1 Download &amp; Placement (fixed temp path; download once, reuse across sessions) <a class="header-anchor" href="#_2-1-download-placement-fixed-temp-path-download-once-reuse-across-sessions" aria-label="Permalink to &quot;2.1 Download &amp; Placement (fixed temp path; download once, reuse across sessions)&quot;">​</a></h3><p><strong>Download URLs: follow the &quot;Link List&quot; in the <a href="./1.EntryGuide.html">Entry Guide</a></strong> (take the &quot;backend service&quot; row for the target machine&#39;s platform; the Linux package is built for Ubuntu 20.04 x86_64). Trial version — mind the license expiry.</p><p><strong>Fixed temp path</strong>: Windows = <code>%TEMP%\\MxCAD\\</code>, Linux = <code>/tmp/MxCAD/</code>. Follow the check steps in the <a href="./1.EntryGuide.html">Entry Guide</a>: first determine what the task needs (conversion program only / backend service needed), then inspect what is in the temp path — nothing there → download the matching zip per need (conversion program only → standalone MxConvert package; backend service needed → MxServiceCode package, which includes the conversion program) and extract it to the temp path; conversion program only present → if only the conversion program is needed, run the expiry check (see &quot;Deployment and Startup Notes&quot;) and use it; if the backend is needed, clear and re-download the backend package; backend package already extracted → run the expiry check + integrity verification, and if incomplete, clear and re-download. <strong>The temp path MUST be cleared before any re-download</strong> (each package has a fixed structure; the backend package is the complete superset). Do not scan other directories on the user&#39;s machine; after the system cleans the temp dir, just re-download.</p><p><strong>All commands run in <code>MxServiceCode\\MxServiceCode</code> (the project directory) under the temp path.</strong></p><h3 id="_2-2-basic-usage-linux-first-use-requires-permission-setup" tabindex="-1">2.2 Basic Usage (Linux first use requires permission setup) <a class="header-anchor" href="#_2-2-basic-usage-linux-first-use-requires-permission-setup" aria-label="Permalink to &quot;2.2 Basic Usage (Linux first use requires permission setup)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 777</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_demo_MxServiceCode.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start_demo_MxServiceCode.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # the script already chmods node, Mx2DNode.node, mxcadassembly, etc.</span></span></code></pre></div><p>If it fails, use <code>./start_demo_systemlib_MxServiceCode.sh</code> instead (uses the native libraries in the systemLib directory).</p><blockquote><p>⚠️ <strong>Built-in Node version limitation (tested)</strong>: <code>bin\\node.exe</code> is <strong>v10.9.0</strong> and supports <strong>CommonJS only</strong> — ESM (<code>import</code> syntax / <code>.mjs</code>) throws <code>SyntaxError</code> directly; there is no <code>fetch</code>, no optional chaining, or other newer features. Helper scripts written for the built-in node must use CommonJS (<code>require</code>) + <code>.js</code>; when you need ESM, use the system Node.</p></blockquote><h2 id="iii-local-reference-docs-must-read" tabindex="-1">III. Local Reference Docs (must read) <a class="header-anchor" href="#iii-local-reference-docs-must-read" aria-label="Permalink to &quot;III. Local Reference Docs (must read)&quot;">​</a></h2><table><thead><tr><th>Doc</th><th>Content</th><th>When to read</th></tr></thead><tbody><tr><td><a href="./4.BackendReferenceDocs/1.MxServiceCodeCommandReference.html">1.MxServiceCodeCommandReference.md</a></td><td>Full reference for the 12 CLI commands (params/return values/call examples) + fileparam JSON passing + how to register a new command</td><td>When calling an existing command</td></tr><tr><td><a href="./4.BackendReferenceDocs/2.Mx2DNodeSecondaryDevAPIReference.html">2.Mx2DNodeSecondaryDevAPIReference.md</a></td><td>All backend parametric drawing/data extraction APIs (Mx2DDraw, MxBackstage, McDbDatabase, McDb* entities, selection sets, geometry objects)</td><td>When developing a new command / custom logic</td></tr><tr><td><a href="./4.BackendReferenceDocs/3.DeploymentAndStartup.html">3.DeploymentAndStartup.md</a></td><td>Directory structure, invocation, Linux permissions, standalone mxcadassembly calls and expiry check, logs, secondary development workflow</td><td>When deploying / troubleshooting</td></tr><tr><td><a href="./4.BackendReferenceDocs/4.SvgDwgKitGuide.html">4.SvgDwgKitGuide.md</a></td><td>mxcad-svg-dwg-kit toolkit: WYSIWYG bidirectional SVG⇄DWG conversion (acquisition, CLI contract, parameter tables, self-check, dev loop for modifying the logic)</td><td>When SVG↔DWG conversion is involved (mxcadassembly does not support SVG)</td></tr></tbody></table><h2 id="iv-task-→-command-selection-quick-reference" tabindex="-1">IV. Task → Command Selection Quick Reference <a class="header-anchor" href="#iv-task-→-command-selection-quick-reference" aria-label="Permalink to &quot;IV. Task → Command Selection Quick Reference&quot;">​</a></h2><p><strong>Before calling any existing command, check against this table that &quot;the command&#39;s contract covers the requirement&quot; — the command name is NOT the selection criterion.</strong> When no existing command covers the task, go straight to secondary development (see the example in section 9 of &quot;Mx2DNodeSecondaryDevAPIReference.md&quot;); do not &quot;try running&quot; a command whose functionality doesn&#39;t match.</p><table><thead><tr><th>What you want to do</th><th>Which path</th><th>Notes</th></tr></thead><tbody><tr><td>Extract text / block attributes</td><td><code>getcaddata</code> (existing)</td><td>⚠️ TEXT + INSERT attributes only, <strong>no geometry entities of any kind</strong></td></tr><tr><td>Extract polyline vertices on a <strong>specified layer</strong></td><td><code>getPolylineTheSpecifiedLayer</code> (existing)</td><td>⚠️ The layer name is hardcoded in <code>GetDwgData.ts</code>; to use across drawings you must change the source and recompile</td></tr><tr><td>Extract <strong>line / circle / other geometry entity</strong> data</td><td>Secondary development</td><td>No existing command; example in section 9 of &quot;Mx2DNodeSecondaryDevAPIReference.md&quot; (<code>modelSpace().getAllEntity()</code> + <code>instanceof McDbXxx</code>)</td></tr><tr><td>Extract the layer list</td><td><code>getAllLayer</code> (existing)</td><td>Outputs <code>&lt;filename&gt;_layers.json</code></td></tr><tr><td>DWG→mxweb conversion</td><td><code>mxcadassembly</code> standalone call</td><td>⚠️ The <code>convert</code> command is deprecated and unusable; the <code>outpath</code> directory must pre-exist</td></tr><tr><td>SVG→DWG / DWG→SVG conversion</td><td>new kit mxcad-svg-dwg-kit (<code>bin\\mxkit.cmd</code> / <code>dist\\mxkit.js</code>)</td><td>⚠️ mxcadassembly does not support SVG; see &quot;4.SvgDwgKitGuide.md&quot;</td></tr><tr><td>Batch cutting by title block frames</td><td><code>frameCut2</code> (existing)</td><td>⚠️ <code>frameCut</code> (v1) depends on the 1337 service and is unavailable in the standalone edition</td></tr><tr><td>Export the whole drawing to PDF</td><td><code>Mx_Custom_ExportPdf</code> (existing)</td><td>Auto-scales to the sheet size</td></tr><tr><td>Merge multiple DWGs</td><td><code>margeDwg</code> (existing)</td><td>Can filter by layer</td></tr><tr><td>Compare the block tables of two drawings</td><td><code>compare_dwg</code> (existing)</td><td></td></tr><tr><td>Parametric drawing (generate a new drawing)</td><td>Secondary development (<code>testParamDraw</code> can serve as a starting template)</td><td>See sections 2 and 9 of &quot;Mx2DNodeSecondaryDevAPIReference.md&quot;</td></tr><tr><td>Read/write extended data (xdata)</td><td>Secondary development</td><td><code>mxtest_getxdata</code> is only a debug example (hardcoded paths; do not use in production)</td></tr></tbody></table><h2 id="v-task-→-doc-lookup-guide" tabindex="-1">V. Task → Doc Lookup Guide <a class="header-anchor" href="#v-task-→-doc-lookup-guide" aria-label="Permalink to &quot;V. Task → Doc Lookup Guide&quot;">​</a></h2><table><thead><tr><th>Task Type</th><th>Doc(s) to Read</th></tr></thead><tbody><tr><td>Calling an existing command (conversion/data extraction/cutting/merge/PDF export/layers/compare)</td><td>&quot;MxServiceCodeCommandReference.md&quot;</td></tr><tr><td>Secondary development: a new command or custom processing logic</td><td>&quot;Mx2DNodeSecondaryDevAPIReference.md&quot; + the project&#39;s <code>src\\sample\\</code> sample code</td></tr><tr><td>Environment deployment / startup failure / Linux permissions / log investigation</td><td>&quot;Deployment and Startup Notes&quot;</td></tr><tr><td>Format conversion parameters (DWG/DXF/MXWEB/PDF/JPG, cut_dwg, print_to_pdf)</td><td>Official &quot;Drawing Conversion Program Tutorial&quot;: <a href="./../8.RelatedArticles/1.IntroductionGuide/3.Drawing Conversion Function Usage Guide.html">link</a></td></tr><tr><td>SVG↔DWG conversion (incl. the SVG→mxweb chain)</td><td>&quot;4.SvgDwgKitGuide.md&quot; (./4.BackendReferenceDocs/4.SvgDwgKitGuide.md)</td></tr><tr><td>Getting started with backend development</td><td>The bundled <code>NODE.JS后台程序开发.doc</code> (teaches development based on this project; not an API doc)</td></tr></tbody></table><h2 id="vi-capability-boundaries-based-on-hands-on-testing-of-the-1-0-trial-version" tabindex="-1">VI. Capability Boundaries (based on hands-on testing of the 1.0 trial version) <a class="header-anchor" href="#vi-capability-boundaries-based-on-hands-on-testing-of-the-1-0-trial-version" aria-label="Permalink to &quot;VI. Capability Boundaries (based on hands-on testing of the 1.0 trial version)&quot;">​</a></h2><p><strong>Capabilities present</strong></p><ul><li>DWG/DXF open and save</li><li>Format conversion: DWG→mxweb, etc. (via standalone <code>mxcadassembly</code> call; see &quot;Deployment and Startup Notes&quot; section 3)</li><li>Parametric drawing: lines, arcs, circles, ellipses, points, text, MText, images, hatches, blocks, title block frames/title blocks, five dimension types</li><li>Data extraction: text, block attributes, polylines, layers, xdata extended data</li><li>Selection sets and filters (by type/layer/window/crossing)</li><li>Entity editing: properties, xdata, explode, intersectWith, getArea</li><li>Drawing merge (with layer filtering), batch cutting by title block frames, drawing comparison</li><li>Export: PDF, JPG, mxweb (the frontend display format)</li><li>System variable read/write (LTSCALE, etc.)</li></ul><p><strong>Development-mode conventions</strong></p><ul><li>New CAD interface features going forward: developed by the AI on top of this project (<code>src\\sample\\</code> pattern + Mx2DNode API)</li><li>After modifying the source, you MUST recompile with <code>npm run build</code> (the runtime executes the .js)</li></ul><p><strong>Limitations</strong></p><ul><li>The <code>convert</code> command is unusable: its wgh output format is deprecated and the native module has removed <code>writeWebGLFile</code> (running it reports <code>code:-4</code>). The mxcad frontend only accepts mxweb; use <code>mxcadassembly</code> directly for DWG→mxweb (see &quot;MxServiceCodeCommandReference.md&quot; detailed 1)</li><li>The <code>frameCut</code> (v1) command depends on a service on port 1337, which the standalone MxServiceCode does not provide — <strong>use <code>frameCut2</code> instead</strong> (it calls mxcadassembly directly and is functionally equivalent)</li><li>Trial version (TryVersion): mind the license expiry and the open-count limit</li><li>Debug commands such as <code>mxtest_getxdata</code> contain hardcoded paths and must not be used directly in production</li><li>The layer filter value of <code>getPolylineTheSpecifiedLayer</code> is hardcoded in the source; modify it for the target drawing before use</li><li><strong>SVG is not supported</strong>: mxcadassembly&#39;s <code>outname</code> only accepts <code>.mxweb/.dwg/.dxf/.pdf/.jpg</code> — any SVG input/output is outside its capabilities; SVG⇄DWG conversion goes through the mxcad-svg-dwg-kit toolkit (see &quot;4.SvgDwgKitGuide.md&quot;)</li></ul>`,36)])])}const u=t(s,[["render",i]]);export{h as __pageData,u as default};
